import os
import re
import subprocess
import sys
from collections import Counter

def out(args):
    return subprocess.check_output(["git"] + args, stderr=subprocess.DEVNULL)

upstream = "{upstream_remote}/{upstream_branch}"
base = out(["merge-base", "HEAD", upstream]).decode().strip()
if not base:
    sys.exit(1)

def changed(rev):
    raw = out(["diff", "--name-only", "-z", base, rev])
    return [os.fsdecode(p) for p in raw.split(b"\0") if p]

def is_lock(path):
    b = os.path.basename(path).lower()
    if b.endswith(".lock") or b.endswith(".lockb"):
        return True
    if re.search(r"-lock\.(json|ya?ml)$", b):
        return True
    return b in ("go.sum", "npm-shrinkwrap.json")

overlap = set(changed("HEAD")) & set(changed(upstream))
for path in overlap:
    if not is_lock(path):
        continue
    try:
        b = out(["show", base + ":" + path])
        u = out(["show", upstream + ":" + path])
        l = out(["show", "HEAD:" + path])
    except subprocess.CalledProcessError:
        continue
    bc = Counter(b.splitlines())
    uc = Counter(u.splitlines())
    lc = Counter(l.splitlines())
    for line, count in bc.items():
        if uc.get(line, 0) == 0 and lc.get(line, 0) > 0:
            sys.exit(0)
sys.exit(1)
